    func exportIcs(id: String, timezone: String, reminder: UInt32?, selection: [String]) async throws  -> String
    
    func history() async throws  -> History
    
    func importPhoto(request: PhotoRequest, job: RecognitionJob) async throws  -> ScanOutcome
    
    /**
     * Same pipeline as a regular import, with retained detector crops for tracing.
     */
    func importTracePhoto(request: PhotoRequest, job: RecognitionJob) async throws  -> ScanOutcome
    
    func jobProgress(id: String)  -> JobProgress?
    
    func loadScan(id: String) async throws  -> ReviewSnapshot
    
    func pageGroup(id: String) async throws  -> [String]
    
    func pdfPages(id: String, count: UInt32) async throws  -> [String]
    
    func planCalendar(id: String) async throws  -> PlanCalendar
    
    func preferences() async throws  -> Preferences
    
    func prepareCalendar(id: String, calendarId: String, timezone: String, reminder: UInt32?, selection: [String], replacement: Bool) async throws  -> Proposal
    
    func prepareUndo(batchId: String) async throws  -> Proposal
    
    func previewDraft(id: String, calendarId: String, timezone: String, reminder: UInt32?) async throws  -> DraftPreview
    
    func previewReplacement(id: String, calendarId: String, timezone: String, reminder: UInt32?) async throws  -> DraftPreview
    
    func recognitionBusy()  -> Bool
    
    /**
     * Full, local recognition evidence for the explicitly opened tracing workspace.
     */
    func recognitionTrace(id: String) async throws  -> String
    
    func reconcileCalendar() async throws  -> [CalendarResult]
    
    /**
     * Register before installing a cancellation handler or publishing the job.
