public 
enum AppError: Swift.Error, Equatable, Hashable, Foundation.LocalizedError {

    
    
    case Validation(message: String
    )
    case Storage(message: String
    )
    case ExpiredScan
    case StaleRevision
    case StaleProposal
    case PermissionDenied
    case UncertainWrite
    case Busy
    case Cancelled
    case Timeout(operation: String
    )

    

    

    
    public var errorDescription: String? {
        String(reflecting: self)
    }
    
}

#if compiler(>=6)
extension AppError: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeAppError: FfiConverterRustBuffer {
    typealias SwiftType = AppError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> AppError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .Validation(
            message: try FfiConverterString.read(from: &buf)
            )
        case 2: return .Storage(
            message: try FfiConverterString.read(from: &buf)
            )
        case 3: return .ExpiredScan
        case 4: return .StaleRevision
        case 5: return .StaleProposal
        case 6: return .PermissionDenied
        case 7: return .UncertainWrite
        case 8: return .Busy
        case 9: return .Cancelled
        case 10: return .Timeout(
            operation: try FfiConverterString.read(from: &buf)
            )

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: AppError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case let .Validation(message):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(message, into: &buf)
            
        
        case let .Storage(message):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(message, into: &buf)
            
        
        case .ExpiredScan:
            writeInt(&buf, Int32(3))
        
        
        case .StaleRevision:
            writeInt(&buf, Int32(4))
        
        
        case .StaleProposal:
            writeInt(&buf, Int32(5))
        
        
        case .PermissionDenied:
            writeInt(&buf, Int32(6))
        
        
        case .UncertainWrite:
            writeInt(&buf, Int32(7))
        
        
        case .Busy:
            writeInt(&buf, Int32(8))
        
        
        case .Cancelled:
            writeInt(&buf, Int32(9))
        
        
        case let .Timeout(operation):
            writeInt(&buf, Int32(10))
            FfiConverterString.write(operation, into: &buf)
            
        }
    }
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeAppError_lift(_ buf: RustBuffer) throws -> AppError {
    return try FfiConverterTypeAppError.lift(buf)
}

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeAppError_lower(_ value: AppError) -> RustBuffer {
    return FfiConverterTypeAppError.lower(value)
}



public enum ArchiveStatus: Equatable, Hashable {
    
    case reconciliationNeeded
    case undone
    case saved
    case partiallySaved
    case recognitionPending
    case readyForReview





}

#if compiler(>=6)
extension ArchiveStatus: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeArchiveStatus: FfiConverterRustBuffer {
    typealias SwiftType = ArchiveStatus

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> ArchiveStatus {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .reconciliationNeeded
        
        case 2: return .undone
        
        case 3: return .saved
        
        case 4: return .partiallySaved
        
        case 5: return .recognitionPending
        
        case 6: return .readyForReview
        
        default: throw UniffiInternalError.unexpectedEnumCase
