        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_reha_ffi_checksum_func_appointment_issues() != 21990) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_reha_ffi_checksum_func_confirm_appointment_fields() != 32228) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_reha_ffi_checksum_func_new_appointment() != 21238) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_reha_ffi_checksum_func_open_application() != 49466) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_reha_ffi_checksum_func_decode_assistant_request() != 22203) {
        return InitializationResult.apiChecksumMismatch
